results.raw:
beat 3
retain token_row, context_vec
camera frame=[token_row, context_vec, dist_chart, sampled_mat] min_zoom=0.80
@cue:project
chart dist_chart type=bars data=[mat:0.62, rug:0.18, floor:0.11, chair:0.09] dock=right-of:context_vec
link proj_arrow from=context_vec to=dist_chart
@cue:top_prob
focus dist_chart item=mat
@cue:sample_draw
show sampled_mat label="mat" dock=below:dist_chart
@cue:append_tok
move sampled_mat to=right-of:token_row

beat 3
retain token_row, context_vec
camera frame=[token_row, context_vec, dist_chart, sampled_mat] min_zoom=0.80
@cue:project
chart dist_chart type=bars data=[mat:0.62, sat:0.14, on:0.09, the:0.07, dog:0.05] dock=right-of:context_vec
link proj_arrow from=context_vec to=dist_chart style=flow
@cue:top_prob
focus dist_chart item=mat
@cue:sample_draw
show sampled_mat label="mat" dock=below:dist_chart z=overlay
@cue:append_tok
move sampled_mat to=right-of:tok_the2 duration=0.6
